CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS accounts_context (
	id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
	content     text NOT NULL,
	metadata    jsonb NOT NULL DEFAULT '{}'::jsonb,
	embedding   vector(3072) NOT NULL,
	document_id text GENERATED ALWAYS AS (metadata ->> 'document_id') STORED,
	source      text GENERATED ALWAYS AS (metadata ->> 'source') STORED,
	created_at  timestamptz NOT NULL DEFAULT now(),
	updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS accounts_context_document_id_idx ON accounts_context (document_id);
CREATE INDEX IF NOT EXISTS accounts_context_source_idx ON accounts_context (source);
CREATE INDEX IF NOT EXISTS accounts_context_metadata_idx ON accounts_context USING gin (metadata jsonb_path_ops);

CREATE OR REPLACE FUNCTION accounts_context_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
	NEW.updated_at = now();
	RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS accounts_context_set_updated_at ON accounts_context;
CREATE TRIGGER accounts_context_set_updated_at
	BEFORE UPDATE ON accounts_context
	FOR EACH ROW EXECUTE FUNCTION accounts_context_set_updated_at();

CREATE TABLE IF NOT EXISTS inbox_suggestions (
	id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
	message_id  text NOT NULL UNIQUE,
	sender      text,
	subject     text,
	status      text NOT NULL CHECK (status IN ('pending_review', 'suggested', 'approved', 'rejected')),
	analysis    jsonb NOT NULL,
	created_at  timestamptz NOT NULL DEFAULT now(),
	reviewed_at timestamptz,
	reviewed_by text
);

